const p = $input.first().json.body || {};
const data = p.data || {};
const dyn = (data.conversation_initiation_client_data && data.conversation_initiation_client_data.dynamic_variables) || {};
const collected = (data.analysis && data.analysis.data_collection_results) || {};
const turns = Array.isArray(data.transcript) ? data.transcript : [];
const transcript = turns.length
  ? turns.map(t => `${t.role}: ${t.message || ''}`).join('\n')
  : ((data.analysis && data.analysis.transcript_summary) || '');
function outcomeFromSuccess(s) {
  if (s === 'success') return 'confirmed';
  if (s === 'failure') return 'no_answer';
  return undefined;
}
const out = {
  leadId: dyn.lead_id,
  callType: dyn.call_type === 'reconfirmation' ? 'reconfirmation' : 'initial',
  elevenlabsId: data.conversation_id,
  transcript,
  outcome: (collected.outcome && collected.outcome.value) || outcomeFromSuccess(data.analysis && data.analysis.call_successful),
  sentiment: collected.sentiment && collected.sentiment.value,
  duration: data.metadata && data.metadata.call_duration_secs,
};
Object.keys(out).forEach(k => out[k] === undefined && delete out[k]);
return [{ json: out }];
